from pathlib import Path
import json,html
R=Path('pages/READINGS/the-giver'); esc=html.escape
pages=[('index','Start Here'),('chapters','Chapter Reading Guide'),('plot','Plot and Structure'),('setting','Setting and World-Building'),('characters','Characters and Relationships'),('conflicts','Conflicts'),('themes','Themes'),('freedom','Freedom, Choice, and Control'),('memory','Memory, Pain, and Wisdom'),('individuality','Individuality and Sameness'),('love','Love, Family, and Human Connection'),('language','Language, Truth, and Manipulation'),('responsibility','Coming of Age and Moral Responsibility'),('symbols','Motifs and Symbols'),('techniques','Style and Techniques'),('writing','Writing Workshop'),('assessment','Assessment and Revision'),('sources','Sources')]
titles=dict(pages)
def p(t): return f'<p>{t}</p>'
def section(t,b,id=''):return f'<section class="panel"'+(f' id="{id}"' if id else '')+f'><h2>{t}</h2>{b}</section>'
def table(headers,rows):
 out='<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable study table"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'
 for row in rows:
  out+='<tr>'+''.join(('<th scope="row">'+v+'</th>') if i==0 else ('<td>'+v+'</td>') for i,v in enumerate(row))+'</tr>'
 return out+'</tbody></table></div>'

def ul(xs):return '<ul>'+''.join('<li>'+x+'</li>' for x in xs)+'</ul>'
def response(id,label):return f'<div class="response"><label for="{id}">{label}</label><textarea id="{id}" data-save="{id}" rows="5" placeholder="Write a claim, add evidence, and explain how it supports your thinking."></textarea><button type="button" data-clear="{id}">Reset this response</button></div>'
def details(title,body):return f'<details><summary>{title}</summary>{body}</details>'
def link(k,label=None):return f'<a href="{k}.html">{label or titles[k]}</a>'
def cycle(name,ex,why,q,task):return section(name,p(ex)+p('<strong>Interpretation:</strong> '+why)+p('<strong>Discuss:</strong> '+q)+p('<strong>Write:</strong> '+task))
def full(b):return '<div class="spoiler-gate"><p>Full-novel analysis is hidden. Choose “Full novel” above when you are ready. Chapter-by-chapter notes remain available in the reading guide.</p></div><div class="full-content" hidden>'+b+'</div>'
def shell(k,body,subtitle):
 n=[x[0] for x in pages].index(k)
 nav=''.join(f'<a href="{slug}.html"'+(' aria-current="page"' if slug==k else '')+(' class="subnav"' if slug in ['freedom','memory','individuality','love','language','responsibility'] else '')+f'>{title}</a>' for slug,title in pages)
 pager='<nav class="pager" aria-label="Study sequence">'+(link(pages[n-1][0],'← '+pages[n-1][1]) if n else '<span></span>')+(link(pages[n+1][0],pages[n+1][1]+' →') if n+1<len(pages) else link('index','Back to Start Here'))+'</nav>'
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{titles[k]} · The Giver | HuskyDaddy</title><meta name="description" content="Grade 8 novel study of The Giver: {esc(subtitle)}"><link rel="stylesheet" href="study.css"><script src="study.js" defer></script></head><body data-page="{k}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="../../../index.html">🐾 HuskyDaddy</a><nav aria-label="Website"><a href="../../readingtips.html">Reading courses</a><a href="../../contact.html">Contact</a></nav></header><div class="layout"><aside><div class="book-mark" aria-hidden="true">THE<br>GIVER<span></span></div><p class="eyebrow">LOIS LOWRY · GRADE 8</p><details class="course-menu" open><summary>Study navigation</summary><nav aria-label="Novel study">{nav}</nav></details></aside><main id="main"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../../readingtips.html">Reading</a> / <a href="index.html">The Giver</a> / <span>{titles[k]}</span></nav><div class="toolbar"><label for="spoilers">Spoiler setting <select id="spoilers"><option value="light">Spoiler-light</option><option value="full">Full novel · spoilers</option></select></label><div class="print-controls"><button type="button" id="print">Print page</button><label class="print-option"><input type="checkbox" id="print-teacher"> Include teacher answers in print</label></div></div><p class="mode-note" id="mode-note" role="status"></p><header class="page-heading"><p class="eyebrow">A HUSKYDADDY NOVEL STUDY</p><h1>{titles[k]}</h1><p class="lede">{subtitle}</p></header><noscript><p class="notice">JavaScript is required to reveal full-novel analysis and chapter notes. Use a browser with JavaScript enabled. Spoilers stay hidden by default.</p></noscript><div id="lesson">{body}</div>{pager}<footer><p>Original teaching materials · Use your copy of the novel as the primary evidence.</p><p>Optional responses and reading progress are stored only in this browser, under this website address. They are not sent to a teacher. Shared-device users should reset their work.</p><button type="button" id="reset-all">Reset all Giver responses and progress</button><p id="save-status" role="status" aria-live="polite"></p><a href="sources.html">Sources and verification limits</a></footer></main></div></body></html>'''
 (R/(k+'.html')).write_text(doc)

intro=section('What would you give up to feel safe?',p('Jonas lives in a community that values order and predictability. As an important childhood ceremony approaches, he begins to notice questions that familiar explanations cannot settle. Read to explore who makes decisions, what people need from one another, and how language shapes what they understand.')+p('This course moves from <strong>what happens</strong> to <strong>how the novel creates meaning</strong>. Read the novel first; the notes support rather than replace it.'))
intro+=section('Your learning route','<ol><li>Read a chapter and record one event, one question, and one detail.</li><li>Use the chapter guide without opening chapters you have not read.</li><li>After finishing, connect patterns in setting, character, conflict, and technique.</li><li>Turn a topic into an arguable theme statement.</li><li>Draft a paragraph with evidence, then revise using the rubric.</li></ol>'+p('<strong>Learning goals:</strong> distinguish observation from inference; explain how literary choices shape meaning; support and qualify interpretations; discuss respectfully; revise writing for a reader. These goals connect with BC English Language Arts 8, rather than covering its entire curriculum.'))
intro+=section('Choose your next step','<div class="cards">'+''.join(f'<a class="card" href="{slug}.html"><span class="card-number">{i:02}</span><h3>{title}</h3><p>'+({'chapters':'All 23 chapters, reading progress, and a printable log.','themes':'Six paths from a topic to a defensible interpretation.','writing':'Build, support, and revise a literary argument.','assessment':'Use clear criteria to plan your next revision.'}.get(slug,'Explore evidence, interpretations, discussion, and writing practice.'))+'</p><span>Open section →</span></a>' for i,(slug,title) in enumerate(pages[1:7]+pages[13:],1))+'</div>')
intro+=section('Read with control',p('Start in spoiler-light mode. Most analysis pages contain full-novel interpretations and stay hidden until you choose Full novel. The reading guide has its own “Read up to Chapter…” limit. Changing to Full novel does not automatically mark chapters as read. Links from chapter notes to wider analysis carry a spoiler warning.')+p('Later chapters include death, the killing of an infant, and discussion of a death by request. Ask your teacher for support or an alternative way to engage if needed.'))
shell('index',intro,'From careful reading to a thoughtful literary argument.')

plot=section('A structure is an argument about emphasis',p('Exposition establishes the situation. Rising action increases complications. A climax is a decisive turning point in the main conflict. Falling action follows its consequences; resolution shows what has changed or remains unsettled. A novel can complicate this familiar pattern.'))
plot+=full(section('Interactive plot diagram','''<svg class="plot" viewBox="0 0 700 220" role="img" aria-labelledby="plot-title"><title id="plot-title">A possible plot arc: introduction, growing knowledge, revelation, departure, unresolved ending</title><path d="M25 185 L150 170 L390 30 L500 120 L675 160" fill="none" stroke="currentColor" stroke-width="3"/><g fill="#963b35"><circle cx="25" cy="185" r="6"/><circle cx="150" cy="170" r="6"/><circle cx="390" cy="30" r="6"/><circle cx="500" cy="120" r="6"/><circle cx="675" cy="160" r="6"/></g><g font-size="14" fill="currentColor"><text x="20" y="210">1</text><text x="145" y="195">2</text><text x="385" y="20">3</text><text x="495" y="145">4</text><text x="670" y="185">5</text></g></svg>'''+''.join(details(t,p(b)) for t,b in [
('1 · Exposition · Chapters 1–8','Family rituals, age ceremonies, and the selection establish Jonas’s world and the unusual role he will occupy. His uncertainty makes an orderly community feel less secure.'),
('2 · Rising action · Chapters 9–18','Exceptions in the instructions and increasingly demanding memories separate Jonas from others. Colour, pain, love, and Rosemary’s story expose costs that ordinary community explanations omit.'),
('3 · One defensible climax · Chapter 19','Watching his father kill the smaller twin transforms Jonas’s understanding of release. Knowledge becomes morally urgent: he can no longer accept ordinary participation. This is a strong climax if the central conflict is his awakening to society’s violence.'),
('4 · Consequences and renewed danger · Chapters 20–22','The plan and the sudden escape follow the revelation. Calling all of this falling action is imperfect: the flight creates a fresh survival conflict. Chapter 21 is a plausible alternative climax if the central conflict is whether Jonas will act against society.'),
('5 · An open resolution · Chapter 23','The hill, sled, lights, and music offer hope without confirming safe arrival. Physical escape and moral change do not receive equally definite resolutions.')]))+cycle('Arguing about an ending','In Chapter 23, Jonas perceives lights and music as he descends with Gabriel.','These perceptions can support a hopeful arrival reading. Exhaustion, cold, and the return of familiar memory imagery also allow a reading in which his perceptions do not confirm survival. The novel alone does not settle it; later books should not be used to erase the ambiguity of this ending.','Which detail most strongly challenges your preferred reading?','Defend one interpretation, then acknowledge one detail that keeps it uncertain.')+response('plot-response','Which turning point would you defend as the climax, and why?'))
shell('plot',plot,'Map events, then ask what your map emphasizes.')

setting=section('Three kinds of setting',p('<strong>Physical:</strong> land, buildings, weather, and spaces. <strong>Social:</strong> institutions, customs, work, and relationships. <strong>Psychological:</strong> the atmosphere of expectations and feelings people live within. The novel does not give a precise real-world location or calendar date.'))
setting+=full(table(['Apparently ideal','Hidden cost','Evidence and interpretation'],[
('Predictable physical environment','Reduced variety and dependence on control','Climate and terrain were altered for Sameness (Ch. 11). Practical efficiency is purchased through lost experience.'),('Carefully selected jobs','Limited self-determination','The Ceremony assigns adult roles (Chs. 7–8). Recognition of ability does not equal a free choice.'),('Stable family units','Attachments are institutionally limited','Spouses and children are assigned; adult family units eventually dissolve (Chs. 2, 13, 16). Care exists inside a restricted structure.'),('Polite, orderly language','Some realities become difficult to name','Love is corrected as imprecise (Ch. 16); release masks killing (Ch. 19). Precision can coexist with concealment.'),('Safety from painful memories','A concentrated burden and weak shared judgement','The Receiver advises others using knowledge they do not hold (Chs. 13–14). Safety depends on unequal knowledge.')])+cycle('A room can reveal a system','The Annex contains books, a lock, and a speaker the Giver can switch off (Ch. 10).','The physical space embodies a social exception: one person can access knowledge and privacy denied to most others. Setting limits who can question decisions.','Does the room suggest freedom, confinement, or both?','Compare the Annex with a family dwelling. Explain how one physical difference creates a social difference.')+cycle('Sameness shapes the possible','Outside the community, Jonas faces rough land, hunger, and changing weather (Ch. 22).','The contrast prevents a simple safe-world/bad-world division. Leaving control creates room for experience but also genuine vulnerability.','Would an argument about freedom change if the outside world were effortless?','Explain how Chapter 22 qualifies rather than cancels Jonas’s criticism of Sameness.')+response('setting-response','Choose one rule. Explain how it shapes a character’s choices.'))
shell('setting',setting,'Look beyond the scenery: a world teaches people what seems possible.')

chars=[('Jonas','Major · protagonist','Careful, observant, increasingly questioning. His desire to understand becomes a willingness to protect Gabriel.','Word choice (Ch. 1), selection (Ch. 8), release recording (Ch. 19), escape (Ch. 21).','His development connects knowledge with ethical action, although courage does not remove doubt or danger.'),('The Giver','Major · mentor and co-agent','Knowledgeable, burdened, compassionate; moves from carrying suffering alone toward planning change.','Painful training (Chs. 14–15), Rosemary’s history (Ch. 18), decision to remain (Ch. 20).','His mentorship shows that wisdom includes responsibility to people who have not yet learned.'),('Gabriel','Major in the central action · dependent and catalyst','Vulnerable and responsive to care; he receives soothing memories and needs protection.','Pale eyes (Ch. 3), shared memory (Ch. 14), threatened release and escape (Ch. 21).','His needs turn Jonas’s objections into urgent personal responsibility; he is not merely an abstract symbol.'),('Jonas’s father','Important supporting character','Attentive and gentle within his assigned role, yet capable of lethal obedience.','Extra care for Gabriel (Chs. 1–3), twin recording (Ch. 19).','The contradiction challenges the idea that a pleasant manner guarantees ethical judgement. His full inner understanding is not narrated.'),('Jonas’s mother','Minor · representative of institutional values','Practical and rule-oriented; offers reassurance through accepted systems.','Justice work (Ch. 1), Stirrings pills (Ch. 5), language about love (Ch. 16).','She helps show how ordinary family care can reinforce social limits.'),('Lily','Minor · younger sister and social learner','Talkative, curious, and quick to repeat community assumptions.','Anger at a visitor (Ch. 1), comments on eyes and Birthmothers (Ch. 3), ceremonies (Ch. 6).','Her remarks reveal how attitudes are learned before they are critically examined.'),('Asher','Minor · friend and foil','Playful and socially integrated; shaped by correction and suited to recreation work.','Assignment speech (Ch. 7), disagreement over war play (Ch. 17).','His different response shows what Jonas’s unusual knowledge has done to their shared world.'),('Fiona','Minor · friend and emotional connection','Gentle and caring; accepts an institutional caregiving role.','Volunteering (Ch. 4), assignment (Ch. 7), hair (Ch. 12), war-game encounter (Ch. 17).','Her kindness complicates any claim that everyone in the community is simply cruel. The novel does not give us her interior viewpoint.'),('The Chief Elder','Minor · ceremonial authority','Assured and publicly attentive to individual strengths.','Assignments and Jonas’s selection (Chs. 7–8).','Her speech legitimizes the system by making decisions sound personal, wise, and protective.')]
characters=section('Who matters, and how?',p('Major characters sustain the central action or development; minor characters can still be essential to a theme. These categories are useful judgements, not official rankings. Jonas is the protagonist. The Giver is his mentor, while Gabriel is central to the action despite having little speech.'))
characters+=full(section('Character studies',''.join(details(name+' · '+role,p('<strong>Traits and motivation:</strong> '+traits)+p('<strong>Evidence:</strong> '+ev)+p('<strong>Narrative role:</strong> '+rolewhy)+p('<strong>Discuss:</strong> Which event most strongly supports this account of '+name+'? What does it leave uncertain?')+p('<strong>Write:</strong> Make a claim about '+name+'’s role. Use one event above, explain a choice or contrast, and connect it to a theme rather than listing traits.')) for name,role,traits,ev,rolewhy in chars))+
section('A relationship map','<div class="relationship-map"><div class="map-centre">JONAS</div>'+''.join('<div><strong>'+a+'</strong><span>'+b+'</span></div>' for a,b in [('Giver ↔ Jonas','Memory, trust, mentorship, and a shared plan'),('Jonas → Gabriel','Care grows into protection'),('Parents ↔ Jonas','Nurturing routines become a conflict over truth'),('Asher & Fiona ↔ Jonas','Friendship strained by unequal experience'),('Lily ↔ Jonas','Sibling familiarity reveals learned assumptions'),('Chief Elder → Jonas','Authority publicly defines his role')])+'</div>'+p('Arrows describe relationships, not control over every action. See the studies above for chapter evidence.'))+
section('Jonas’s development timeline','<ol class="timeline"><li><strong>Chs. 1–5:</strong> accepts routines while noticing puzzles.</li><li><strong>Chs. 8–12:</strong> receives unusual responsibilities and new perception.</li><li><strong>Chs. 13–17:</strong> experience creates empathy, frustration, and distance.</li><li><strong>Chs. 19–21:</strong> knowledge becomes a decision to resist and protect.</li><li><strong>Chs. 22–23:</strong> acts under uncertainty; responsibility survives the loss of comfort.</li></ol>')+
cycle('Direct and indirect characterization','The Chief Elder directly lists Jonas’s qualities (Ch. 8). His decision to take Gabriel with him indirectly reveals his priorities through action (Ch. 21).','A direct statement can tell readers what a community values; actions let readers judge those values under pressure. The two forms may reinforce or complicate each other.','Does the Elder’s account explain everything about the person Jonas becomes?','Compare one named quality with one later action. Explain the relationship instead of simply calling Jonas brave.')+response('characters-response','Explain one relationship that changes Jonas.'))
shell('characters',characters,'Judge traits through choices, relationships, and the limits of what we can know.')

conflicts=section('A conflict has pressure on both sides',p('Character versus society involves institutions or shared expectations. Character versus self involves competing values, fears, or desires. Character versus character involves people whose goals or understandings collide. A single scene can contain more than one kind.'))
conflicts+=full(table(['Conflict','Choice','Consequence','Theme connection'],[('Jonas vs society: assigned limits','Questions Sameness after learning colour (Chs. 12–13)','He sees alternatives but struggles with arguments about safety.','Freedom requires judgement, not merely permission.'),('Jonas vs self: comfort or truth','Stops taking pills (Ch. 16)','He gains stronger feelings and becomes less able to fit familiar routines.','Awareness can disrupt belonging.'),('Jonas vs Asher: war play','Asks the children to stop (Ch. 17)','Asher feels challenged; shared friendship no longer means shared understanding.','Experience can create empathy and separation.'),('Jonas vs Father’s institutional role','Takes Gabriel away (Ch. 21)','Protects him from immediate release but exposes them to real danger.','Care may require disobedience without guaranteeing success.'),('Giver vs self and society','Stays to help people after the planned departure (Ch. 20)','Accepts the burden of supporting collective change.','Responsibility can take different forms.')])+cycle('Conflict develops through changed understanding','Jonas does not object to the war game because the rules forbid it (Ch. 17). He objects because a memory changes what it means to him.','The disagreement reveals a clash between lived understanding and harmless-seeming habit. Asher’s reaction does not prove deliberate cruelty.','Can people resolve a conflict if they lack shared knowledge?','Trace the pressure, choice, and consequence in this encounter; connect the result to a qualified theme.')+response('conflict-response','Trace a conflict through two chapters. What changes, and why?'))
shell('conflicts',conflicts,'Follow the choices that turn disagreement into development.')
# Original theme arguments and classroom models; evidence is paraphrased.
themes={
'freedom':dict(eq='When does protection become control?',topic='choice',claims=['A society that removes difficult choices can protect people from some harms while weakening their ability to make informed moral decisions.','Meaningful freedom includes accepting responsibility for uncertainty, rather than expecting every decision to be safe.'],development='Jonas initially trusts assigned roles. Colour makes him imagine alternatives, although he still fears wrong choices. Knowledge of release finally makes obedience unacceptable. His escape does not remove danger; it makes him responsible for responding to it.',moments=[('Chs. 2, 7–8','Jonas and Chief Elder','Ceremonial diction','Assignments present adult decisions as recognition, narrowing the space for self-direction.'),('Chs. 12–13','Jonas and Giver','Colour and dialogue','Perceiving difference helps Jonas imagine choice, but his hesitation shows the persistence of social conditioning.'),('Chs. 19–21','Jonas, Father, Gabriel','Revelation and accelerated pacing','The recording makes delay ethically costly; an urgent choice replaces a carefully prepared plan.'),('Ch. 22','Jonas and Gabriel','Setting and contrast','Hunger makes the costs of freedom real without making Gabriel’s threatened death acceptable.')],model='Lowry presents freedom as a difficult responsibility rather than an easy escape from rules. When Jonas begins seeing colour, he imagines choosing between things but also repeats the community’s fear of wrong choices (Chs. 12–13). His hesitation shows that control has shaped how he thinks, not just what he may do. Later, taking Gabriel away forces him to confront hunger and exposure (Chs. 21–22). This contrast prevents the outside world from becoming a simple reward. Jonas gains the power to act, but he must also care for someone whose survival is uncertain. The novel therefore questions safety purchased by surrendering judgement, while acknowledging that independent decisions can have painful costs.',questions=['Who chooses Jonas’s adult work?','Why does Jonas partly defend restrictions even after seeing colour?','Does the danger outside weaken his case against Sameness, or make his decision more meaningful?'],task='Claim: control protects ___ but limits ___. Add one early example of an assigned decision and one later choice. Explain how the contrast changes the meaning of safety.',prompt='To what extent does the novel distinguish freedom from comfort? Develop a qualified argument using two stages of Jonas’s journey.',mis='Freedom does not mean that every rule is harmful, or that leaving solves every problem. Do not describe Jonas as fully independent from the beginning.',related=['responsibility','individuality']),
'memory':dict(eq='What can painful knowledge teach that comfort cannot?',topic='memory',claims=['Shared knowledge of suffering can deepen moral judgement, while concentrating that knowledge in one person protects others at the cost of collective understanding.','Memory becomes a source of wisdom when people use it to respond to others, rather than merely preserving it in isolation.'],development='Pleasurable memories first show Jonas a wider world. Pain then teaches him about vulnerability and public decisions. Rosemary’s story shows that memories affect communities, and the Giver’s plan makes helping others understand them part of his duty.',moments=[('Chs. 10–11','Jonas and Giver','Sensory imagery','Learning becomes an experience of snow and warmth rather than a list of information.'),('Chs. 14–15','Jonas, Giver, wounded soldier','Embodied pain and concentrated pacing','The sled injury and battlefield build knowledge that comfortable routines cannot supply.'),('Ch. 18','Rosemary and Giver','Embedded narrative','Returned memories expose the community’s lack of preparation to face suffering.'),('Ch. 20','Giver and Jonas','Contrasting decisions','Staying to help makes wisdom a relationship of care, not a private possession.')],model='The novel connects memory with judgement by showing what an apparently safe community cannot understand. In Chapter 14, the Giver explains that memories of hunger help him advise against choices that could cause starvation. The memories have practical value because they make consequences imaginable before they happen. Yet the people receiving the advice do not share the experience behind it. Lowry places knowledge and suffering together in the Receiver’s role, exposing an inequality hidden beneath collective comfort. The Giver’s later decision to remain and help people face returned memories (Ch. 20) suggests a different possibility: wisdom could involve guiding others through pain instead of keeping them permanently protected from it.',questions=['What advice does memory help the Giver provide?','Why is holding memory both an honour and a burden?','Can suffering produce wisdom by itself, or does the novel make response to suffering equally important?'],task='State what memory makes possible. Paraphrase one moment of painful learning. Explain how the knowledge changes a decision or a relationship, then qualify the cost.',prompt='Is the community’s central problem the absence of memories or the unequal responsibility for them? Consider both in your argument.',mis='Do not claim all pain is good or automatically makes people wise. The novel shows trauma, care, and the need for support.',related=['responsibility','love']),
'individuality':dict(eq='How can belonging preserve difference rather than erase it?',topic='difference',claims=['Sameness offers predictable belonging by reducing visible differences, but it also limits the experiences through which people understand themselves and others.','Individual perception can begin resistance, although seeing differently does not immediately give a person the language or support needed to act.'],development='Early comments about eyes establish discomfort with difference. Jonas’s selection distinguishes him publicly. Colour and memory allow him to imagine what has disappeared, but his inability to share those experiences creates loneliness.',moments=[('Ch. 3','Jonas, Gabriel, Lily','Eye and apple motifs','Small differences create questions before Jonas knows how to interpret them.'),('Ch. 8','Jonas and Chief Elder','Ceremonial contrast','The community honours an exception while continuing to define his role for him.'),('Chs. 12–13','Jonas and Giver','Colour imagery','Difference becomes valuable as a source of beauty and possibility.'),('Ch. 17','Jonas, Asher, Fiona','Limited viewpoint and contrast','New awareness separates friends who still inhabit the same physical world.')],model='Jonas’s changing perception makes individuality both enriching and isolating. In Chapter 12, learning to name colour gives him a way to understand the strange changes he has noticed. Colour is literally a new part of his experience, but it can also represent alternatives suppressed by Sameness. In Chapter 13, he cannot simply make Asher share that perception. This failed connection matters because the novel does not present individual discovery as an instantly successful solution. Jonas can see more while communicating less effectively with people he likes. His development suggests that preserving difference requires more than exceptional individuals: it also requires relationships and language capable of supporting what those individuals discover.',questions=['Why does Lily’s comment about pale eyes make Jonas uncomfortable?','How is being selected different from choosing an identity?','Can a society honour one exceptional role while still suppressing individuality?'],task='Claim that difference brings both ___ and ___. Use an early detail and a later failed connection. Explain the change in Jonas’s understanding.',prompt='Analyse the tension between individuality and belonging without assuming they must always be opposites.',mis='Sameness is not simply everyone dressing alike. It includes decisions about perception, work, relationships, knowledge, and feeling.',related=['freedom','language']),
'love':dict(eq='What makes care more than a well-performed duty?',topic='love and family',claims=['Organized care can meet practical needs while remaining emotionally limited when lasting attachment and difficult understanding are discouraged.','Love becomes ethically demanding when protecting a particular person requires risk rather than simply following accepted routines.'],development='Family rituals and nurturing show real attention to needs. Memories introduce a deeper emotional vocabulary, and the parents’ response to love exposes a mismatch. Jonas’s care for Gabriel then becomes a reason to break rules and endure danger.',moments=[('Chs. 1–4','Father, Gabriel, Jonas, Larissa','Domestic routines and intimate care','The community contains tenderness; its limits should not erase evidence of care.'),('Ch. 14','Jonas and Gabriel','Parallel memory transmission','A private ability becomes a way to soothe another person.'),('Ch. 16','Jonas, parents, remembered family','Juxtaposition and diction','The family memory makes Jonas question a language that cannot express his new understanding.'),('Chs. 21–23','Jonas and Gabriel','Protective action and unresolved ending','Love motivates persistence without guaranteeing that persistence will succeed.')],model='Jonas’s relationship with Gabriel turns love from an unfamiliar word into a demanding practice. In Chapter 14, he uses a peaceful memory to help the baby sleep. This act already goes beyond obeying a public instruction: he responds to a particular person’s need. After learning that Gabriel will be released, Jonas leaves with him before the escape plan is ready (Ch. 21). The change in pacing makes care urgent and costly. He cannot wait for ideal conditions because the baby does not have time. Lowry therefore connects love with responsibility under uncertainty, while the open ending prevents readers from confusing a loving choice with a guaranteed happy result.',questions=['How does Father show care for Gabriel early in the novel?','Why is the parents’ response to love disappointing to Jonas?','Can genuine care coexist with participation in a harmful system? How should an argument acknowledge both?'],task='Identify one caring action. Explain what it costs or risks. Connect the action to a theme that distinguishes attachment from duty without claiming all duty is empty.',prompt='Compare family care and Jonas’s care for Gabriel. What does each relationship reveal about the possibilities and limits of love?',mis='The novel does not require the claim that every community member feels nothing. Distinguish limited emotional understanding from total absence of care.',related=['responsibility','memory']),
'language':dict(eq='Can words be precise and still conceal the truth?',topic='language',claims=['A demand for approved language can improve surface accuracy while discouraging people from naming experiences that challenge authority.','Euphemism makes harmful practices easier to accept when people lack the knowledge needed to test official descriptions against reality.'],development='Jonas begins by carefully selecting a word for a feeling. Later, permission to lie unsettles the apparent equality of truthfulness. Love exposes limits in the approved vocabulary; the recording finally reveals what release has concealed.',moments=[('Ch. 1','Jonas and family','Self-correction and controlled diction','Careful naming looks reasonable but also makes conformity part of private thought.'),('Ch. 9','Jonas','Irony and internal questioning','A rule permitting lies undermines his trust in other rules and speakers.'),('Ch. 16','Jonas and parents','Dialogue and contrast','Correcting love as imprecise narrows what the family can recognize.'),('Ch. 19','Jonas, Father, Giver','Euphemism and revelation','The gap between a gentle term and a lethal action becomes impossible for Jonas to ignore.')],model='Lowry shows that a word can sound harmless while hiding an action’s moral weight. Before Chapter 19, release belongs to the community’s familiar vocabulary of rules and ceremonies. When Jonas watches his father kill the smaller twin, the recording forces the word into contact with an event he can now recognize. The effect depends on gradual revelation: readers have encountered the term before receiving the knowledge needed to judge it. Father’s gentle manner intensifies the contradiction rather than explaining it away. Through this gap between description and action, the novel suggests that evaluating language requires evidence and experience, not simply confidence that an approved term is accurate.',questions=['Why is permission to lie disturbing to Jonas?','How does the meaning of release change for him?','Who is responsible when institutional language prevents people from understanding harm? Distinguish evidence from inference.'],task='Choose an approved word. Describe its ordinary use, then a moment that challenges it. Explain how the reader’s changed understanding supports your claim.',prompt='Does the community misuse language deliberately, or does its restricted knowledge also limit its speakers? Make a qualified argument.',mis='Precision is not inherently dishonest. Analyse how and when the demand for precision becomes restrictive. Do not assume every speaker knowingly lies.',related=['individuality','freedom']),
'responsibility':dict(eq='When does understanding create a duty to act?',topic='growing up',claims=['Moral maturity involves testing inherited expectations against consequences, even when doing so threatens a person’s belonging.','Responsibility can require either leaving a harmful system or staying to help change it; the ethical value lies in the purpose and consequences of the choice.'],development='Jonas moves from trusting adult decisions to evaluating their effects. Pain and emotional experience make familiar behaviour look different. The Giver and Jonas eventually choose different roles in a shared attempt at change.',moments=[('Chs. 1–2','Jonas and parents','Limited narration','His first concern is how well authority will choose for him, not whether it should.'),('Chs. 15–17','Jonas, Giver, Asher','Memory and contrast','Encountering suffering changes how he responds to ordinary play and feeling.'),('Chs. 19–20','Jonas and Giver','Revelation and dialogue','Recognizing harm leads to a plan, with distinct duties for each participant.'),('Chs. 21–22','Jonas and Gabriel','Accelerated action and survival conflict','Jonas takes responsibility without possessing complete preparation or control.')],model='The Giver and Jonas show that responsibility cannot be measured by a single outward action. In Chapter 20, Jonas wants his teacher to leave with him, but the Giver decides to remain and help the community face returned memories. His choice differs from passive obedience because its purpose is to support change. Jonas’s departure serves another need: returning memories and, when events accelerate, protecting Gabriel (Ch. 21). Placing these decisions together prevents a simple claim that leaving is always courageous and staying always cowardly. The novel instead asks readers to judge what a decision responds to, whom it protects, and what burdens the person is prepared to accept.',questions=['Why does Jonas initially rely on his parents’ reassurance?','What changes between discomfort with the rules and a decision to act?','How can the Giver’s decision to stay and Jonas’s decision to leave both express responsibility?'],task='Compare two choices. State each purpose, support it with a chapter event, and explain how the comparison complicates an easy judgement about courage.',prompt='Is Jonas’s coming of age primarily a change in knowledge, feeling, or action? Explain their relationship rather than selecting one without qualification.',mis='Growing older does not automatically produce wisdom. Do not assume action is responsible just because it breaks a rule.',related=['freedom','love'])}
for slug,d in themes.items():
 body=section('Essential question',p(d['eq']))+section('From topic to theme',p(f'<strong>Topic:</strong> {d["topic"]}. A topic names an area of interest; a theme statement argues what the novel suggests about it. A defensible statement allows evidence and qualification. It is not an instruction everyone must obey.'))
 body+=full(section('Two defensible arguments',ul(d['claims'])+p('These interpretations are starting points, not the novel’s official answers.'))+section('How the theme develops',p(d['development']))+section('Evidence → interpretation',table(['Moment','Characters','Technique','Interpretation'],d['moments']))+section('Model analytical paragraph',p(d['model'])+p('<small>Original teaching model using paraphrases. Chapter references locate events for study; add page citations from your edition before submitting formal work.</small>'))+section('Discuss in increasing depth','<ol>'+''.join('<li>'+q+'</li>' for q in d['questions'])+'</ol>')+section('Scaffolded paragraph',p(d['task'])+p('Use: claim → accurate evidence → explanation of a technique or choice → connection to the theme. Include a qualification such as “although,” “while,” or “does not necessarily.”')+response(slug+'-draft','Draft your paragraph'))+section('Independent writing',p(d['prompt']))+section('A common misconception',p(d['mis']))+section('Follow the connections',p('Related themes: '+', '.join(link(x) for x in d['related'])+'.')+p('Revisit '+link('characters')+', '+link('conflicts')+', and '+link('techniques')+' for evidence and methods. These sections include full-novel spoilers.')))
 shell(slug,body,d['eq'])
shell('themes',section('A topic is not yet an argument',p('Memory is a topic. “Memory can make compassion possible while imposing painful responsibilities” is a theme statement. Build statements that explain a relationship, tension, or condition. Avoid slogans such as “Always be yourself.”'))+section('Six connected investigations','<div class="cards">'+''.join('<a class="card" href="'+k+'.html"><span class="card-number">'+str(i).zfill(2)+'</span><h2>'+titles[k]+'</h2><p>'+v['eq']+'</p><span>Explore this theme →</span></a>' for i,(k,v) in enumerate(themes.items(),1))+'</div>')+section('Try the move',p('Choose a topic. Add what changes, why it matters, and a qualification. Test the result against at least two moments. If one moment challenges it, revise the claim rather than hiding the evidence.')+response('theme-builder','Write a topic, then turn it into a complete theme statement.')),'Six investigations into the tensions that make the novel worth discussing.')

symbols=section('Pattern or object?',p('A <strong>motif</strong> is a recurring element that gathers meaning through repetition and change. A <strong>symbol</strong> is an object, image, or action that carries significance beyond its literal role. One element can do both jobs. Repetition alone does not prove a single fixed meaning, and an isolated detail needs careful support before being called a motif.'))
symbols+=full(table(['Element','Pattern and references','Possible meaning, with limits'],[('Colour','Apple (Ch. 3), red (Ch. 12), expanding perception (Ch. 13)','A motif of discovering difference and alternatives. Literal perception comes first; colour does not automatically mean goodness.'),('Seeing and eyes','Pale eyes (Ch. 3), Capacity to See Beyond (Ch. 8), colour explanation (Ch. 12)','Seeing can suggest insight, but unusual eyes do not by themselves prove moral superiority.'),('Memory','Pleasure (Ch. 11), pain (Chs. 14–15), Rosemary’s history (Ch. 18)','Repeated transmission connects knowledge, burden, and empathy. Memories are experiences within the story as well as a thematic pattern.'),('Dreams','Fiona dream (Ch. 5), sled dream (Ch. 12)','Private experiences exceed public routines. Do not treat every dream as a reliable prediction.'),('Precision of language','Self-correction (Ch. 1), Asher’s punishment history (Ch. 7), love (Ch. 16)','A language motif exposes the tension between accuracy and acceptable expression.'),('Sled','Pleasure (Ch. 11), injury (Ch. 14), final descent (Ch. 23)','A recurring object can symbolize movement into experience, including pleasure and risk. Its last appearance supports hope and uncertainty together.')])+cycle('The same object can change its meaning','The sled offers delight, becomes a vehicle of pain, and returns at the ending (Chs. 11, 14, 23).','The sequence makes a one-word equation such as “sled = happiness” inadequate. Repeated experience complicates the symbol rather than simply confirming it.','How does the painful ride change a hopeful reading of the final descent?','Trace the sled through three appearances. Make a claim about change, not just repetition.')+response('symbols-response','Explain a motif through two or more appearances.'))
shell('symbols',symbols,'Trace repetition, notice change, and avoid one-word symbol answers.')

tech=section('How readers learn beside Jonas',p('The novel uses <strong>third-person limited narration centred on Jonas</strong>: it refers to him in the third person but primarily gives access to his thoughts and perceptions. Readers receive explanations as he encounters them. A narrator’s report of what Jonas thinks is not proof that his interpretation is complete.'))
tech+=full(table(['Technique','Example or reference','Effect','Theme connection'],[('Controlled diction','Jonas corrects his description of fear (Ch. 1)','Makes social expectations visible inside ordinary thought.','Language can guide and restrict self-understanding.'),('Euphemism','Release acquires a horrifying meaning (Ch. 19)','Softens a practice until evidence exposes what it hides.','Accepted language needs ethical scrutiny.'),('Gradual revelation','Apple to hair to red (Chs. 3, 12)','The reader’s uncertainty follows Jonas’s learning.','Understanding requires more than familiar labels.'),('Foreshadowing','Warnings about severe training pain (Ch. 8), fulfilled in Chs. 14–15','Creates expectation without revealing the exact experience.','Honour and burden are intertwined.'),('Sensory imagery','Snow and sunshine (Ch. 11); battlefield (Ch. 15)','Makes lost experiences immediate rather than merely informational.','Knowing includes feeling consequences.'),('Contrast','Family memory and parents’ response (Ch. 16)','Exposes two emotional frameworks in close succession.','Orderly care may have relational limits.'),('Symbolism','Sled across Chs. 11, 14, 23','Connects delight, danger, and an uncertain destination.','Freedom and experience resist simple guarantees.'),('Irony','Gentle nurturing manner during the twin’s death (Ch. 19)','Conflicts with what the action means to Jonas.','Obedience can coexist with harm.'),('Pacing','Departure accelerates when Gabriel faces release (Ch. 21)','Replaces prepared discussion with immediate action.','Responsibility may precede readiness.'),('Ambiguity','Lights and music through exhausted perception (Ch. 23)','Allows competing interpretations without independent confirmation.','Hope can exist without certainty.')]))
tech+=section('Figurative language is a narrower category',p('A simile makes an explicit comparison, often using “like” or “as.” A metaphor describes one thing in terms of another. Personification gives human qualities to something nonhuman. Narration, pacing, irony, and foreshadowing are broader techniques, not automatically figures of speech.')+p('This site does not label unverified lines from the novel as metaphors or similes. Find a candidate in your own copy, record its exact wording and page, and explain the comparison before naming it. Not every vivid description is figurative language.'))
tech+=section('Compare two original teaching examples',p('<strong>These passages are teacher-written examples, not quotations from Lowry.</strong>')+table(['Neutral description','Descriptive passage'],[('The corridor was quiet. A bell rang. Mara stopped at the door.','The bell cut through the corridor’s silence like a snapped wire. Mara’s hand hovered above the handle.')])+p('The second passage uses a simile to make the sound feel sharp, a metaphorical verb (“cut”), and a precise physical action that suggests hesitation. It does not explain Mara’s feelings directly.')+p('<strong>Discuss:</strong> What inference can you support about Mara, and what remains unknown?')+p('<strong>Write:</strong> Describe the same doorway as welcoming. Change sensory details and diction while keeping the basic event.')+response('techniques-response','Explain one language choice and its effect on a reader.'))
shell('techniques',tech,'Name a method only after you can explain what it does.')

writing=section('Summary tells; analysis explains',table(['Summary','Analysis'],[('Jonas searches for an accurate word for his feelings in Chapter 1.','The opening self-correction places social expectations inside Jonas’s private thinking, encouraging readers to question how fully he controls his own language.')])+p('An analytical paragraph still needs accurate summary as evidence. Its purpose is to explain why selected details matter, not retell every event.'))
writing+=section('A paragraph you can take apart','''<div class="tab-set"><div role="tablist" aria-label="Paragraph workshop"><button role="tab" aria-selected="true" aria-controls="model-overview" id="tab-overview">Overview</button><button role="tab" aria-selected="false" aria-controls="model-evidence" id="tab-evidence" tabindex="-1">Evidence</button><button role="tab" aria-selected="false" aria-controls="model-analysis" id="tab-analysis" tabindex="-1">Analysis</button><button role="tab" aria-selected="false" aria-controls="model-practice" id="tab-practice" tabindex="-1">Practice</button></div><div role="tabpanel" id="model-overview" aria-labelledby="tab-overview"><p><strong>Claim:</strong> Lowry’s opening makes careful language a sign of both self-awareness and social pressure. <strong>Evidence:</strong> Jonas rejects his first description of his feelings and searches for a word that better matches his situation (Ch. 1). <strong>Explanation:</strong> Because the narration follows the correction inside his thoughts, the reader sees that precision is more than an external rule. It has become a habit through which he understands himself. <strong>Connection:</strong> The moment raises a question about whether approved language helps a person recognize experience or limits the ways it can be expressed.</p></div><div role="tabpanel" id="model-evidence" aria-labelledby="tab-evidence" hidden><p>The model paraphrases a specific action from the publisher’s Chapter 1 excerpt. It does not invent a page number. In submitted work, find the passage in your edition and cite that page.</p></div><div role="tabpanel" id="model-analysis" aria-labelledby="tab-analysis" hidden><p>The explanation names a method—access to thought through limited narration—and traces its effect. “This shows he uses language” would only repeat the evidence. The model instead explains how an external expectation operates as an internal habit.</p></div><div role="tabpanel" id="model-practice" aria-labelledby="tab-practice" hidden><p>Revise “Jonas is different, and this shows difference is important.” Name one kind of difference, locate one event available at your reading stage, and explain a consequence. End with a theme statement that allows a qualification.</p></div></div>''')
writing+=section('Integrating and citing evidence',p('Choose a short phrase because its wording matters. Introduce it with your own sentence, preserve the original meaning, and explain its effect afterward. For example, the Chapter 1 publisher excerpt begins with “It was almost December.” The seasonal opening locates Jonas near an anticipated change; that observation needs explanation, not just a quotation.')+p('<strong>Citation pattern, not a finished citation:</strong> Lowry describes [your exact short quotation] ([page from your edition]). Or: [Your sentence and quotation] (Lowry [page]). Do not repeat Lowry’s name in parentheses when it already identifies the source in your prose. Put the sentence’s closing punctuation after the parenthetical citation in an ordinary short quotation.')+p('A paraphrase uses your own wording and sentence structure while accurately representing the source. It still needs a citation when it refers to a specific passage. Keep the boundary between the source’s idea and your interpretation clear. Do not merely replace a few words with synonyms.')+p('Use page numbers from your own edition when available. This site’s chapter references help you locate events; they are not a universal replacement for MLA page citations. For an unpaginated edition, follow the MLA guidance appropriate to that format and your teacher’s instructions; never invent a page number or rely on unstable device locations.')+p('Long prose quotations of more than four typed lines generally use block format; this unit emphasizes short, purposeful evidence. Consult the official MLA guidance linked on the Sources page for quotation formatting.'))
writing+=section('Build your Works Cited entry',p('<strong>Complete from your edition’s title and copyright pages:</strong>')+p('Lowry, Lois. <em>The Giver</em>. [Edition if stated and relevant], [Publisher of your edition], [Year of your edition].')+p('Brackets mark information you must supply and remove. Omit an edition statement if none is given. For an e-book, add applicable format or container information following MLA guidance. Do not copy the audiobook’s publication details into a print-book citation. Alphabetize a Works Cited list and use a hanging indent; cite secondary guides too if you use their ideas.')+response('edition-notes','Record the bibliographic details of your edition.'))
writing+=section('Repair three common problems',table(['Draft problem','Revision move','Try it'],[('Vague: “The community is bad.”','Name a specific system and its consequence.','Argue how one rule changes a person’s choices.'),('Unsupported: “Jonas is responsible.”','Add a precise action, with a chapter locator or page citation.','Explain what someone risks or protects through the action.'),('Repetitive: “This shows control because they are controlled.”','Explain the mechanism and its effect.','Who decides, what alternative disappears, and why does that matter?')])+response('writing-draft','Draft and revise an analytical paragraph.'))
shell('writing',writing,'Make an arguable claim, select evidence, and explain the connection.')

rubric=[('Meaning','Names a topic or retells events; interpretations need clearer evidence and accuracy.','Offers a relevant claim and some evidence; explanation is partial or occasionally too broad.','Makes a defensible theme-related claim, selects accurate evidence, and explains how details support the interpretation.','Develops a nuanced argument, tests it against tensions or alternative readings, and integrates well-chosen evidence without overstating certainty.'),('Style','Uses vague or repetitive wording; technique labels may not fit the example.','Uses some precise vocabulary; explanation and sentence variety are uneven.','Uses clear analytical language, accurate literary terms, and varied sentences suited to a Grade 8 reader and task.','Controls emphasis and sentence movement purposefully; precise language handles complexity without unnecessary jargon.'),('Form','Ideas lack a clear sequence; evidence may appear without introduction or follow-up.','Has a recognizable paragraph structure; some links between claim, evidence, and explanation are weak.','Organizes a focused paragraph or essay with integrated evidence, logical explanation, and a clear connection to the argument.','Shapes structure around the argument, using transitions and placement of counterpoints to guide a reader through a complex line of reasoning.'),('Conventions','Frequent sentence, spelling, or punctuation errors obscure meaning; citation information is often missing.','Meaning is generally understandable; errors and incomplete citation patterns require revision.','Uses sentence boundaries, spelling, punctuation, and the assignment’s taught MLA conventions consistently enough to communicate clearly.','Edits with purposeful control and strong consistency; integrates and documents evidence smoothly, with errors rare and meaning precise.')]
assessment=section('A teaching rubric, not an official VSB document',p('This teacher-created adaptation uses Meaning, Style, Form, and Conventions to assess literary analysis in this unit. It is informed by BC ELA 8 and VSB/Provincial Proficiency Scale guidance. The descriptors below are original classroom adaptations, not official VSB descriptors.')+p('<strong>Proficient means meeting Grade 8 expectations.</strong> Extending means greater depth, nuance, and purposeful control within the learning—not simply more words, harder vocabulary, or perfect spelling. No percentage conversions are assigned here. MLA requirements are assignment-specific expectations explicitly taught in this unit.'))
assessment+=section('Literary analysis rubric',table(['Criterion','Emerging','Developing','Proficient · meets expectations','Extending'],rubric))
assessment+=section('Self-assess with evidence',p('For each criterion, choose a level and point to a sentence in your draft that supports the choice. Then name one attainable revision. Your judgement is a starting point for feedback, not an automatic grade.')+''.join(f'<label class="assessment-choice" for="level-{r[0]}">{r[0]} <select id="level-{r[0]}" data-save="level-{r[0]}"><option value="">Choose after reading your draft</option>'+''.join(f'<option>{l}</option>' for l in ['Emerging','Developing','Proficient','Extending'])+'</select></label>' for r in rubric)+response('self-assessment','Evidence for my judgement and my next revision'))
checks=['My claim makes an argument rather than naming a topic.','I checked events and chapter boundaries in the novel.','My evidence is specific and accurately quoted or paraphrased.','I explain how a detail or technique supports my interpretation.','I distinguish what happens from what I infer.','I acknowledge a tension or plausible alternative where useful.','My paragraph has a logical sequence and clear connections.','I verified page numbers and edition details rather than guessing.','I edited sentence boundaries, punctuation, spelling, and citation format.']
assessment+=section('Revision checklist',''.join(f'<label class="check"><input type="checkbox" data-save="revision-{i}"> {t}</label>' for i,t in enumerate(checks))+p('Revise Meaning and Form before polishing Style and Conventions. Ask a partner to underline the claim, box the evidence, and mark the sentence that most clearly explains the link.'))
shell('assessment',assessment,'Use feedback to make a stronger next draft, not just attach a label.')
chapters=json.loads((R/'chapters.json').read_text())
chapterbody=section('Read alongside your own copy',p('Set the last chapter you have finished. Later entries—including their titles and teacher responses—remain hidden. Every chapter entry uses only knowledge available by that point. Summaries and event examples are original paraphrases; the interpretation sections explain what the events may suggest. Expand an entry to read it; these notes are not a substitute for reading the novel.')+p('Progress and responses are saved only in this browser. Full-novel mode does not change your chapter limit.')+'<label for="chapter-limit">Read up to Chapter… <select id="chapter-limit"><option value="0">Not started</option>'+''.join(f'<option value="{i}">{i}</option>' for i in range(1,24))+'</select></label><p id="reading-progress" role="status"></p><nav class="chapter-menu" aria-label="Chapter menu">'+''.join(f'<a href="#chapter-{i}" data-chapter-link="{i}" hidden>{i}</a>' for i in range(1,24))+'</nav>')
chapterbody+='<div id="chapter-not-started" class="notice">Choose a completed chapter above to reveal your reading guide.</div>'
for c in chapters:
 i=c['number']
 content='<div class="chapter-summary"><p class="eyebrow">SUMMARY · EVENTS</p>'+p(c['summary'])+'</div>'
 content+='<h3>Key developments</h3>'+ul(c['developments'])+'<h3>Characters</h3>'+p(c['characters'])+p(c['characterInsight'])+'<div class="analysis-box"><h3>Literary focus · interpretation</h3>'+p(c['focus'])+p(c['literaryAnalysis'])+'<h3>Theme connection</h3>'+p(c['themeAnalysis'])+p('Explore '+link(c['theme'])+' <strong>(destination contains later spoilers; hidden unless Full novel is selected)</strong>.')+'</div>'
 content+='<h3>Reading questions</h3>'+p('<strong>Comprehension:</strong> '+c['comprehension'])+p('<strong>Analysis:</strong> '+c['analysis'])+'<h3>Writing practice</h3>'+p(c['prompt']+' Write a short paragraph with an arguable claim, an accurate detail from '+('Chapter 1' if i==1 else 'Chapters 1–'+str(i))+', and an explanation of how the detail supports your claim. Use a page number from your own edition when available.')+response('chapter-response-'+str(i),'My Chapter '+str(i)+' paragraph')
 content+='<div class="teacher-content">'+details('Teacher suggestions · deliberately open to view',p('<strong>Display feature only—not secure access control.</strong> Suggested responses are possibilities, not a marking script. A different supported reading may be valid.')+p('<strong>Comprehension check:</strong> '+c['comprehensionAnswer'])+p('<strong>Analytical suggested answer:</strong> '+c['analyticalAnswer'])+p('<strong>Look for in writing:</strong> a focused claim; a specific detail from this chapter or an earlier one; an explanation of its effect. Ask students to distinguish the event from their inference.'))+'</div>'
 content+=p('Wider study: '+', '.join(link(k) for k in ['plot','characters','techniques'])+'. <strong>Warning: these destinations include later events in Full novel mode.</strong>')
 content+='<nav class="chapter-pager" aria-label="Chapter '+str(i)+' navigation">'+(f'<a href="#chapter-{i-1}" data-chapter-link="{i-1}">← Previous chapter</a>' if i>1 else '<span>First chapter</span>')+(f'<a href="#chapter-{i+1}" data-chapter-link="{i+1}" hidden>Next chapter →</a><span data-next-locked="{i+1}">Next chapter hidden until marked read</span>' if i<23 else '<span>Final chapter</span>')+'</nav>'
 chapterbody+=f'<details class="chapter" id="chapter-{i}" data-chapter="{i}" hidden><summary>Chapter {i} · {c["title"]}</summary>{content}</details>'
chapterbody+='<div data-retrospective hidden>'+full(section('After finishing the novel · retrospective interpretation',p('Only revisit these connections after Chapter 23. The apple and Fiona’s hair become part of a developing pattern of seeing (Chs. 3, 12). Early uncertainty about release is transformed by the recording (Ch. 19). The first sled ride, painful ride, and final descent connect pleasure, risk, and hope (Chs. 11, 14, 23). These later connections should not be treated as facts Jonas already knows in early chapters.')+p('Discuss: which early detail changed most when you reread it? Distinguish an early prediction from a retrospective interpretation.')))+'</div>'
chapterbody+=section('Printable reading log',p('Print a blank log for notes as you read. It includes numbered rows only, with no later chapter events.')+'<button type="button" id="print-log">Print reading log only</button><div id="reading-log"><h3>The Giver · Reading Log</h3><p>Name: ____________________ &nbsp; Edition: ____________________</p>'+table(['Chapter','Main event','Character insight','Question','Theme'],[(str(i),'','','','') for i in range(1,24)])+'</div>')
shell('chapters',chapterbody,'Read one chapter at a time, keep a record, and develop an interpretation without jumping ahead.')

sources=section('Primary source: the novel',p('Lowry, Lois. <em>The Giver</em>. Use the edition assigned in class. Record its publisher, edition statement if applicable, and publication year from the book itself. This site does not assign one universal set of page numbers.')+p('<a href="https://penguinrandomhousehighereducation.com/book/?isbn=9780553751376">Penguin Random House Higher Education: The Giver, Chapter 1 excerpt</a> — authorized Chapter 1 excerpt used to verify the opening and the short quotation in the writing workshop. The linked product is an audiobook; its bibliographic details are not a template for your print edition.'))
sources+=section('Secondary study guides',ul(['<a href="https://www.sparknotes.com/lit/giver/">SparkNotes: The Giver Study Guide</a> — plot and interpretation cross-checks.','<a href="https://www.sparknotes.com/lit/giver/sparklets/">SparkNotes: Sparklet Chapter Summaries</a> and the linked grouped chapter analyses.','<a href="https://www.cliffsnotes.com/literature/g/the-giver/summary-and-analysis/chapters-12">CliffsNotes: Summary and Analysis, Chapters 1–2</a> — use its contents menu for the other chapter groups.'])+p('Grouped chapter guides were consulted across the novel. Their interpretations are secondary perspectives, not statements of authorial intention. All explanations, summaries, models, activities, and design here are original teaching material. No affiliation or endorsement is implied.'))
sources+=section('Curriculum and assessment',ul(['<a href="https://curriculum.gov.bc.ca/curriculum/english-language-arts/8/core">BC Curriculum: English Language Arts 8</a> — connects reading strategies, interpretation, literary elements, communication, and revision.','<a href="https://www.vsb.bc.ca/prince-wales/assessment-and-reporting">VSB, Prince of Wales Secondary: Assessment and Reporting</a> — context for Grade 8–9 proficiency reporting and self-assessment.','<a href="https://www.vsb.bc.ca/david-thompson/proficiency-scale-explained">VSB, David Thompson Secondary: Proficiency Scale Explained</a>.','<a href="https://www2.gov.bc.ca/assets/gov/education/administration/kindergarten-to-grade-12/unpacking-the-proficency-scale-support-for-educators.pdf">BC Ministry: Unpacking the Proficiency Scale—Support for Educators</a>.'])+p('The four-criterion unit rubric is a teacher-created adaptation, not an official VSB assessment document. It assigns no official percentage conversions.'))
sources+=section('Official MLA guidance',ul(['<a href="https://style.mla.org/in-text-citations-overview/">MLA Style Center: In-Text Citations—An Overview</a>.','<a href="https://style.mla.org/integrating-quotations-college/">MLA Style Center: Integrating Quotations in Research Writing: A Lesson for College Students</a> — an older teaching resource marked as eighth-edition material; read alongside the current overview.','<a href="https://style.mla.org/paraphrase-of-many-sentences/">MLA Style Center: If my paraphrase consists of several sentences, should a citation for the original source appear after each sentence?</a> — an older post explicitly marked as relating to the eighth edition; use alongside current ninth-edition overview guidance.','<a href="https://style.mla.org/works-cited/citations-by-format/">MLA Style Center: Citations by Format</a> — Works Cited entries based on applicable core elements.']))
sources+=section('Verification and limits',p('Sources checked 2 November 2026. Publicly accessible SparkNotes and CliffsNotes sections were available, though SparkNotes also displays subscription prompts. BC curriculum, VSB, and MLA pages were accessible. The Ministry proficiency PDF returned a temporary 502 on direct retrieval during this revision; its indexed official text was available and checked. Only the authorized opening excerpt was available as primary text during preparation; a complete authorized copy was not available in this workspace. Chapter events were cross-checked against secondary guides, but full primary-text verification of every chapter remains a teacher review task before classroom adoption.')+p('The only novel quotation here is the short opening phrase verified in the publisher excerpt. Other novel evidence is paraphrased. Teacher-written descriptive examples are clearly labelled. No page numbers, edition details, or authorial intentions have been invented. Interpretations are presented as arguable readings, not facts about what Lowry intended.'))
shell('sources',sources,'Use the novel as evidence, and know what each supporting source can establish.')

